body.script:
                    (function () {
                        var form = document.getElementById('sh_action_form');
                        var actionInput = document.getElementById('sh_action');
                        var assignmentIdsInput = document.getElementById('sh_assignment_ids');
                        var userIdInput = document.getElementById('sh_user_id');
                        var employeeIdInput = document.getElementById('sh_employee_id');
                        var lotIdInput = document.getElementById('sh_lot_id');
                        var qtyInput = document.getElementById('sh_quantity');
                        var noteInput = document.getElementById('sh_note');
                        var returnAssignmentIdInput = document.getElementById('sh_return_assignment_id');
                        var returnModeInput = document.getElementById('sh_return_mode');

                        var assignModal = document.getElementById('sh_assign_modal');
                        var returnModal = document.getElementById('sh_return_modal');
                        var historyModal = document.getElementById('sh_history_modal');
                        var deliveryHistoryModal = document.getElementById('sh_delivery_history_modal');
                        var userDetailsModal = document.getElementById('sh_user_details_modal');
                        var reassignmentHistoryModal = document.getElementById('sh_reassignment_history_modal');
                        var pendingSignaturesModal = document.getElementById('sh_pending_signatures_modal');
                        var openAssign = document.getElementById('sh_open_assign');
                        var openReturn = document.getElementById('sh_open_return');
                        var openHistory = document.getElementById('sh_open_history');
                        var openDeliveryHistory = document.getElementById('sh_open_delivery_history');
                        var openReassignmentHistory = document.getElementById('sh_open_reassignment_history');
                        var openPendingSignatures = document.getElementById('sh_open_pending_signatures');
                        var userDetailsButtons = document.querySelectorAll('.sh_user_details_btn');
                        var userDetailsBody = document.getElementById('sh_user_details_body');
                        var userDetailsClose = document.getElementById('sh_user_details_close');
                        var assignCancel = document.getElementById('sh_assign_cancel');
                        var assignConfirm = document.getElementById('sh_assign_confirm');
                        var returnCancel = document.getElementById('sh_return_cancel');
                        var returnConfirm = document.getElementById('sh_return_confirm');
                        var historyClose = document.getElementById('sh_history_close');
                        var deliveryHistoryClose = document.getElementById('sh_delivery_history_close');
                        var reassignmentHistoryClose = document.getElementById('sh_reassignment_history_close');
                        var pendingSignaturesClose = document.getElementById('sh_pending_signatures_close');
                        var replaceModal = document.getElementById('sh_replace_modal');
                        var replaceCancel = document.getElementById('sh_replace_cancel');
                        var replaceConfirm = document.getElementById('sh_replace_confirm');
                        var replaceButtons = document.querySelectorAll('.sh_replace_btn');

                        var assignUser = document.getElementById('sh_assign_user');
                        var assignProduct = document.getElementById('sh_assign_product');
                        var assignSerial = document.getElementById('sh_assign_serial');
                        var assignSerialsList = document.getElementById('sh_assign_serials');
                        var assignNote = document.getElementById('sh_assign_note');
                        var replaceCurrentUser = document.getElementById('sh_replace_current_user');
                        var replaceCurrentEquipment = document.getElementById('sh_replace_current_equipment');
                        var replaceProduct = document.getElementById('sh_replace_product');
                        var replaceSerial = document.getElementById('sh_replace_serial');
                        var replaceSerialsList = document.getElementById('sh_replace_serials');
                        var replaceNote = document.getElementById('sh_replace_note');
                        var replaceAssignmentId = '';
                        var userFilter = document.getElementById('sh_user_filter');
                        var historyUserFilter = document.getElementById('sh_history_user_filter');
                        var deliveryUserFilter = document.getElementById('sh_delivery_user_filter');
                        var reassignmentUserFilter = document.getElementById('sh_reassignment_user_filter');
                        var pendingUserFilter = document.getElementById('sh_pending_user_filter');
                        var returnUserFilter = document.getElementById('sh_return_user_filter');
                        var assignedCards = document.querySelectorAll('.sh_user_card');
                        var historyRows = document.querySelectorAll('.sh_history_row');
                        var deliveryRows = document.querySelectorAll('.sh_delivery_row');
                        var reassignmentRows = document.querySelectorAll('.sh_reassignment_row');
                        var pendingRows = document.querySelectorAll('.sh_pending_row');
                        var returnPickRows = document.querySelectorAll('.sh_return_pick_row');
                        var allSerialRows = [];
                        var allProductNames = [];
                        var selectedReturnId = '';

                        function normalize(txt) {
                            return (txt || '').toLowerCase().trim();
                        }

                        function resolveSelectedProductName() {
                            if (!assignProduct) return '';
                            var val = normalize(assignProduct.value);
                            if (!val) return '';
                            for (var i = 0; i < allProductNames.length; i++) {
                                if (normalize(allProductNames[i]) === val) return allProductNames[i];
                            }
                            return '';
                        }

                        function resolveSelectedProductNameFromInput(productInput) {
                            if (!productInput) return '';
                            var val = normalize(productInput.value);
                            if (!val) return '';
                            for (var i = 0; i < allProductNames.length; i++) {
                                if (normalize(allProductNames[i]) === val) return allProductNames[i];
                            }
                            return '';
                        }

                        function refreshSerialDatalistByInputs(productInput, serialInput, datalistNode) {
                            if (!datalistNode) return;
                            var productName = resolveSelectedProductNameFromInput(productInput);
                            var serialTerm = normalize(serialInput ? serialInput.value : '');
                            datalistNode.innerHTML = '';
                            allSerialRows.forEach(function (row) {
                                if (!productName || normalize(row.productName) !== normalize(productName)) return;
                                if (serialTerm && normalize(row.serial).indexOf(serialTerm) === -1) return;
                                var op = document.createElement('option');
                                op.value = row.serial;
                                datalistNode.appendChild(op);
                            });
                            return productName;
                        }

                        function refreshSerialDatalist() {
                            refreshSerialDatalistByInputs(assignProduct, assignSerial, assignSerialsList);
                        }

                        function closeModal(modal) {
                            if (modal) modal.style.display = 'none';
                        }

                        if (openAssign) {
                            openAssign.addEventListener('click', function () {
                                if (assignProduct) assignProduct.value = '';
                                if (assignSerial) assignSerial.value = '';
                                refreshSerialDatalist();
                                if (assignModal) assignModal.style.display = 'flex';
                            });
                        }
                        if (openReturn) {
                            openReturn.addEventListener('click', function () {
                                if (returnModal) returnModal.style.display = 'flex';
                            });
                        }
                        if (openHistory) {
                            openHistory.addEventListener('click', function () {
                                if (historyModal) historyModal.style.display = 'flex';
                            });
                        }
                        if (openDeliveryHistory) {
                            openDeliveryHistory.addEventListener('click', function () {
                                if (deliveryHistoryModal) deliveryHistoryModal.style.display = 'flex';
                            });
                        }
                        if (openReassignmentHistory) {
                            openReassignmentHistory.addEventListener('click', function () {
                                if (reassignmentHistoryModal) reassignmentHistoryModal.style.display = 'flex';
                            });
                        }
                        if (openPendingSignatures) {
                            openPendingSignatures.addEventListener('click', function () {
                                if (pendingSignaturesModal) pendingSignaturesModal.style.display = 'flex';
                            });
                        }
                        if (assignCancel) assignCancel.addEventListener('click', function () { closeModal(assignModal); });
                        if (returnCancel) returnCancel.addEventListener('click', function () { closeModal(returnModal); });
                        if (historyClose) historyClose.addEventListener('click', function () { closeModal(historyModal); });
                        if (deliveryHistoryClose) deliveryHistoryClose.addEventListener('click', function () { closeModal(deliveryHistoryModal); });
                        if (reassignmentHistoryClose) reassignmentHistoryClose.addEventListener('click', function () { closeModal(reassignmentHistoryModal); });
                        if (pendingSignaturesClose) pendingSignaturesClose.addEventListener('click', function () { closeModal(pendingSignaturesModal); });
                        if (userDetailsClose) userDetailsClose.addEventListener('click', function () { closeModal(userDetailsModal); });
                        if (replaceCancel) replaceCancel.addEventListener('click', function () { closeModal(replaceModal); });
                        if (assignModal) assignModal.addEventListener('click', function (ev) { if (ev.target === assignModal) closeModal(assignModal); });
                        if (returnModal) returnModal.addEventListener('click', function (ev) { if (ev.target === returnModal) closeModal(returnModal); });
                        if (historyModal) historyModal.addEventListener('click', function (ev) { if (ev.target === historyModal) closeModal(historyModal); });
                        if (deliveryHistoryModal) deliveryHistoryModal.addEventListener('click', function (ev) { if (ev.target === deliveryHistoryModal) closeModal(deliveryHistoryModal); });
                        if (reassignmentHistoryModal) reassignmentHistoryModal.addEventListener('click', function (ev) { if (ev.target === reassignmentHistoryModal) closeModal(reassignmentHistoryModal); });
                        if (pendingSignaturesModal) pendingSignaturesModal.addEventListener('click', function (ev) { if (ev.target === pendingSignaturesModal) closeModal(pendingSignaturesModal); });
                        if (userDetailsModal) userDetailsModal.addEventListener('click', function (ev) { if (ev.target === userDetailsModal) closeModal(userDetailsModal); });
                        if (replaceModal) replaceModal.addEventListener('click', function (ev) { if (ev.target === replaceModal) closeModal(replaceModal); });

                        userDetailsButtons.forEach(function (btn) {
                            btn.addEventListener('click', function () {
                                var card = btn.closest('.sh_user_tile');
                                var detail = card ? card.querySelector('.sh_user_detail_data') : null;
                                if (userDetailsBody) {
                                    userDetailsBody.innerHTML = detail ? detail.innerHTML : '
Sin detalles.';
                                }
                                if (userDetailsModal) userDetailsModal.style.display = 'flex';
                            });
                        });

                        if (assignConfirm) {
                            assignConfirm.addEventListener('click', function () {
                                if (!assignUser || !assignUser.value) {
                                    alert('Debe seleccionar un empleado.');
                                    return;
                                }
                                var selectedProductName = resolveSelectedProductName();
                                if (!selectedProductName) {
                                    alert('Debe seleccionar un producto válido.');
                                    return;
                                }
                                if (!assignSerial || !assignSerial.value) {
                                    alert('Debe seleccionar un serial del producto elegido.');
                                    return;
                                }
                                var selectedLot = '';
                                allSerialRows.forEach(function (row) {
                                    if (selectedLot) return;
                                    if (normalize(row.productName) === normalize(selectedProductName) && normalize(row.serial) === normalize(assignSerial.value)) {
                                        selectedLot = row.lotId;
                                    }
                                });
                                if (!selectedLot) {
                                    alert('El serial no corresponde al producto seleccionado.');
                                    return;
                                }
                                actionInput.value = 'assign';
                                assignmentIdsInput.value = '';
                                userIdInput.value = '';
                                employeeIdInput.value = assignUser.value;
                                lotIdInput.value = selectedLot;
                                qtyInput.value = '1';
                                noteInput.value = assignNote ? (assignNote.value || '') : '';
                                form.submit();
                            });
                        }
                        document.querySelectorAll('#sh_assign_products option').forEach(function (op) {
                            if (op.value) allProductNames.push(op.value);
                        });
                        document.querySelectorAll('#sh_assign_lot_data option[data-product-id][data-serial][data-product-name]').forEach(function (op) {
                            allSerialRows.push({
                                lotId: op.value,
                                serial: op.dataset.serial,
                                productName: op.dataset.productName,
                            });
                        });
                        if (assignProduct) {
                            assignProduct.addEventListener('input', function () {
                                if (assignSerial) assignSerial.value = '';
                                refreshSerialDatalist();
                            });
                            assignProduct.addEventListener('change', function () {
                                if (assignSerial) assignSerial.value = '';
                                refreshSerialDatalist();
                            });
                        }
                        if (assignSerial) {
                            assignSerial.addEventListener('input', refreshSerialDatalist);
                            assignSerial.addEventListener('focus', refreshSerialDatalist);
                        }
                        if (replaceProduct) {
                            replaceProduct.addEventListener('input', function () {
                                if (replaceSerial) replaceSerial.value = '';
                                refreshSerialDatalistByInputs(replaceProduct, replaceSerial, replaceSerialsList);
                            });
                            replaceProduct.addEventListener('change', function () {
                                if (replaceSerial) replaceSerial.value = '';
                                refreshSerialDatalistByInputs(replaceProduct, replaceSerial, replaceSerialsList);
                            });
                        }
                        if (replaceSerial) {
                            replaceSerial.addEventListener('input', function () {
                                refreshSerialDatalistByInputs(replaceProduct, replaceSerial, replaceSerialsList);
                            });
                            replaceSerial.addEventListener('focus', function () {
                                refreshSerialDatalistByInputs(replaceProduct, replaceSerial, replaceSerialsList);
                            });
                        }
                        function openReplaceFromButton(btn) {
                            if (!btn) return;
                            replaceAssignmentId = btn.dataset.assignmentId || '';
                            if (replaceCurrentUser) replaceCurrentUser.value = btn.dataset.user || '';
                            var currentEq = (btn.dataset.product || '') + ' | Serial: ' + (btn.dataset.serial || '');
                            if (replaceCurrentEquipment) replaceCurrentEquipment.value = currentEq;
                            if (replaceProduct) replaceProduct.value = '';
                            if (replaceSerial) replaceSerial.value = '';
                            if (replaceNote) replaceNote.value = '';
                            refreshSerialDatalistByInputs(replaceProduct, replaceSerial, replaceSerialsList);
                            if (replaceModal) replaceModal.style.display = 'flex';
                        }

                        replaceButtons.forEach(function (btn) {
                            btn.__bound_inline__ = true;
                            btn.addEventListener('click', function () { openReplaceFromButton(btn); });
                        });
                        document.addEventListener('click', function (ev) {
                            var dynBtn = ev.target.closest('.sh_replace_btn');
                            if (!dynBtn) return;
                            if (dynBtn.__bound_inline__) return;
                            ev.preventDefault();
                            openReplaceFromButton(dynBtn);
                        });

                        if (userFilter) {
                            userFilter.addEventListener('input', function () {
                                var term = normalize(userFilter.value);
                                assignedCards.forEach(function (card) {
                                    var user = normalize(card.dataset.user || '');
                                    card.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }
                        if (historyUserFilter) {
                            historyUserFilter.addEventListener('input', function () {
                                var term = normalize(historyUserFilter.value);
                                historyRows.forEach(function (row) {
                                    var user = normalize(row.dataset.user || '');
                                    row.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }
                        if (deliveryUserFilter) {
                            deliveryUserFilter.addEventListener('input', function () {
                                var term = normalize(deliveryUserFilter.value);
                                deliveryRows.forEach(function (row) {
                                    var user = normalize(row.dataset.user || '');
                                    row.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }
                        if (reassignmentUserFilter) {
                            reassignmentUserFilter.addEventListener('input', function () {
                                var term = normalize(reassignmentUserFilter.value);
                                reassignmentRows.forEach(function (row) {
                                    var user = normalize(row.dataset.user || '');
                                    row.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }
                        if (returnUserFilter) {
                            returnUserFilter.addEventListener('input', function () {
                                var term = normalize(returnUserFilter.value);
                                returnPickRows.forEach(function (row) {
                                    var user = normalize(row.dataset.user || '');
                                    row.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }
                        if (pendingUserFilter) {
                            pendingUserFilter.addEventListener('input', function () {
                                var term = normalize(pendingUserFilter.value);
                                pendingRows.forEach(function (row) {
                                    var user = normalize(row.dataset.user || '');
                                    row.style.display = (!term || user.indexOf(term) !== -1) ? '' : 'none';
                                });
                            });
                        }

                        if (returnConfirm) {
                            returnConfirm.addEventListener('click', function () {
                                var selected = document.querySelector('input[name="sh_return_pick"]:checked');
                                if (!selected || !selected.value) {
                                    alert('Seleccione una asignación activa para devolución.');
                                    return;
                                }
                                selectedReturnId = selected.value;
                                actionInput.value = 'return';
                                assignmentIdsInput.value = '';
                                userIdInput.value = '';
                                employeeIdInput.value = '';
                                lotIdInput.value = '';
                                qtyInput.value = '';
                                noteInput.value = '';
                                returnAssignmentIdInput.value = selectedReturnId;
                                returnModeInput.value = 'confirm';
                                form.submit();
                            });
                        }
                        if (replaceConfirm) {
                            replaceConfirm.addEventListener('click', function () {
                                if (!replaceAssignmentId) {
                                    alert('No se encontró la asignación a reemplazar.');
                                    return;
                                }
                                var selectedProductName = resolveSelectedProductNameFromInput(replaceProduct);
                                if (!selectedProductName) {
                                    alert('Debe seleccionar un producto válido.');
                                    return;
                                }
                                if (!replaceSerial || !replaceSerial.value) {
                                    alert('Debe seleccionar un serial del producto elegido.');
                                    return;
                                }
                                var selectedLot = '';
                                allSerialRows.forEach(function (row) {
                                    if (selectedLot) return;
                                    if (normalize(row.productName) === normalize(selectedProductName) && normalize(row.serial) === normalize(replaceSerial.value)) {
                                        selectedLot = row.lotId;
                                    }
                                });
                                if (!selectedLot) {
                                    alert('El serial no corresponde al producto seleccionado.');
                                    return;
                                }
                                actionInput.value = 'replace';
                                assignmentIdsInput.value = replaceAssignmentId;
                                userIdInput.value = '';
                                employeeIdInput.value = '';
                                lotIdInput.value = selectedLot;
                                qtyInput.value = '1';
                                noteInput.value = replaceNote ? (replaceNote.value || '') : '';
                                form.submit();
                            });
                        }
                    })();
